function azmPickOptions(max,selected,min=0){
 return Array.from({length:max-min+1},(_,i)=>{
  const n=i+min;
  return '<option value="'+n+'" '+(n===selected?'selected':'')+'>'+n+'</option>';
 }).join('');
}
